const output = String($json.output ?? '').trim();

function sanitizeUrl(url) {
  return String(url || '').replace(/[),.;]+$/g, '').trim();
}

function getExtension(url) {
  const p = url.split('?')[0].toLowerCase();
  const m = p.match(/\.([a-z0-9]{2,5})$/i);
  return m ? m[1] : '';
}

function buildItem(url, midia) {
  const pathNoQuery = url.split('?')[0];
  const rawName = decodeURIComponent(pathNoQuery.substring(pathNoQuery.lastIndexOf('/') + 1) || 'arquivo');
  const hasExt = /\.[a-zA-Z0-9]{2,5}$/.test(rawName);
  const fileName = hasExt ? rawName : `${rawName}.bin`;

  const ext = getExtension(url);
  const imageExt = ['jpg', 'jpeg', 'png'];
  const messageType = imageExt.includes(ext) ? 'image' : 'document';

  return { json: { url, midia, fileName, messageType } };
}

// Evita links de página (ex.: YouTube) e mantém apenas arquivos diretos
const allowedExt = ['jpg', 'jpeg', 'png', 'webp', 'gif', 'pdf', 'mp4', 'mov', 'webm'];
function isDirectMedia(url) {
  const p = url.split('?')[0].toLowerCase();
  return allowedExt.some((ext) => p.endsWith(`.${ext}`));
}

const lines = output.split(/\r?\n/);
const items = [];
const seen = new Set();

for (const line of lines) {
  const m = line.match(/^\s*[*-]\s*(.+?):\s*(https?:\/\/\S+)/i);
  if (!m) continue;

  const midia = String(m[1] || '').trim() || 'arquivo';
  const url = sanitizeUrl(m[2]);
  if (!url || seen.has(url)) continue;
  seen.add(url);

  if (!isDirectMedia(url)) continue;
  items.push(buildItem(url, midia));
}

if (items.length === 0) {
  const urls = [...new Set((output.match(/https?:\/\/[^\s)]+/gi) ?? []).map(sanitizeUrl))];
  for (const url of urls) {
    if (!isDirectMedia(url)) continue;
    items.push(buildItem(url, 'arquivo'));
  }
}

if (items.length === 0) {
  return [{ json: { hasMedia: false, output, motivoSemMidia: 'nenhum_link_direto_de_arquivo' } }];
}

return items.map((i) => ({ json: { ...i.json, hasMedia: true, output } }));
